function windowPeaks(loads, k) {
  const dq = new Array(loads.length)
  let head = 0
  let tail = 0
  const out = []
  for (let r = 0; r < loads.length; r++) {
    while (tail > head && loads[dq[tail - 1]] <= loads[r]) tail--
    dq[tail++] = r
    if (dq[head] <= r - k) head++
    if (r >= k - 1) out.push(loads[dq[head]])
  }
  return out
}

