from collections import deque


def window_peaks(loads, k):
    dq = deque()
    out = []
    for r, load in enumerate(loads):
        while dq and loads[dq[-1]] <= load:
            dq.pop()
        dq.append(r)
        if dq[0] <= r - k:
            dq.popleft()
        if r >= k - 1:
            out.append(loads[dq[0]])
    return out
